import React from 'react';
import { Navigate } from 'react-router';
import { useAuth } from '../context/AuthContext';
import { Lock } from 'lucide-react';

interface ProtectedRouteProps {
  children: React.ReactNode;
  requiredRoles?: string[];
  requiredPermissions?: string[];
  fallback?: React.ReactNode;
}

/**
 * Componente para proteger rutas según roles y permisos
 * 
 * Ejemplo:
 * <ProtectedRoute requiredRoles={['ADMINISTRADOR', 'SUPERADMINISTRADOR']}>
 *   <MiComponente />
 * </ProtectedRoute>
 */
export const ProtectedRoute: React.FC<ProtectedRouteProps> = ({
  children,
  requiredRoles = [],
  requiredPermissions = [],
  fallback,
}) => {
  const { isAuthenticated, roles, tienePermiso } = useAuth();

  // Si no está autenticado, redirigir a login
  if (!isAuthenticated) {
    return <Navigate to="/login" replace />;
  }

  // Verificar roles
  if (requiredRoles.length > 0) {
    const tieneRolRequerido = requiredRoles.some((rol) => roles.includes(rol));
    if (!tieneRolRequerido) {
      return (
        fallback || (
          <div className="min-h-screen flex items-center justify-center bg-gray-100">
            <div className="bg-white rounded-lg shadow-lg p-8 text-center max-w-md">
              <Lock size={48} className="mx-auto text-red-500 mb-4" />
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Acceso Denegado</h1>
              <p className="text-gray-600 mb-4">
                No tienes los permisos necesarios para acceder a esta sección.
              </p>
              <p className="text-sm text-gray-500">
                Roles requeridos: {requiredRoles.join(', ')}
              </p>
            </div>
          </div>
        )
      );
    }
  }

  // Verificar permisos
  if (requiredPermissions.length > 0) {
    const tienePermisoRequerido = requiredPermissions.some((perm) => tienePermiso(perm));
    if (!tienePermisoRequerido) {
      return (
        fallback || (
          <div className="min-h-screen flex items-center justify-center bg-gray-100">
            <div className="bg-white rounded-lg shadow-lg p-8 text-center max-w-md">
              <Lock size={48} className="mx-auto text-red-500 mb-4" />
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Acceso Denegado</h1>
              <p className="text-gray-600 mb-4">
                No tienes los permisos necesarios para acceder a esta sección.
              </p>
            </div>
          </div>
        )
      );
    }
  }

  return <>{children}</>;
};

import React, { createContext, useEffect, useState, useContext, ReactNode } from 'react';

// === MODELOS (Entidades) ===

export interface Producto {
  id: string;
  nombre: string;
  cantidad: number;
  empresa: string;
  ganancia: number;
  fechaAsignacion: string;
  fechaTerminacion: string;
  estado: 'Pendiente' | 'En proceso' | 'Terminado';
}

export interface Empleado {
  id: string;
  nombre: string;
  cargo: string;
  documento: string;
  telefono: string;
  fechaIngreso: string;
  estado: 'Activo' | 'Inactivo';
}

export interface RegistroDiario {
  id: string;
  empleadoId: string;
  fecha: string;
  horaEntrada: string;
  horaSalida: string;
  unidadesTotales: number;
  unidadesBuenas: number; // Reemplaza la calificación 1-5 por número entero
  producciones?: ProduccionRegistro[];
}

/** Aporte del empleado vinculado a una orden creada en Producción (`Producto`). */
export interface ProduccionRegistro {
  productoId: string;
  unidadesTotales: number;
  unidadesBuenas: number;
}

export interface TareaAseo {
  id: string;
  accion: string; // Ej. Barrer, Trapear...
  area: string;   // Ej. Sala, Cocina...
  encargado: string;
  completada: boolean;
}

interface BootstrapResponse {
  productos: Producto[];
  empleados: Empleado[];
  registros: RegistroDiario[];
  tareasAseo: TareaAseo[];
}

// === TIPO DEL CONTEXTO ===

interface AppContextType {
  // Productos (Producción)
  productos: Producto[];
  agregarProducto: (prod: Omit<Producto, 'id'>) => void;
  editarProducto: (id: string, prod: Partial<Producto>) => void;
  eliminarProducto: (id: string) => void;

  // Empleados
  empleados: Empleado[];
  agregarEmpleado: (emp: Omit<Empleado, 'id'>) => void;
  editarEmpleado: (id: string, emp: Partial<Empleado>) => void;
  eliminarEmpleado: (id: string) => void;

  // Registros de Empleados
  registros: RegistroDiario[];
  agregarRegistro: (reg: Omit<RegistroDiario, 'id'>) => void;
  eliminarRegistro: (id: string) => void;

  // Aseo
  tareasAseo: TareaAseo[];
  agregarTareaAseo: (tarea: Omit<TareaAseo, 'id'>) => void;
  editarTareaAseo: (id: string, tarea: Partial<TareaAseo>) => void;
  toggleTareaAseo: (id: string) => void;
  eliminarTareaAseo: (id: string) => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

/** En dev, Vite reenvía /api → backend (vite.config). En prod, define VITE_API_BASE_URL al desplegar el API. */
const fromEnv = import.meta.env.VITE_API_BASE_URL as string | undefined;
const API_BASE = fromEnv && fromEnv.trim() !== '' ? `${fromEnv.trim()}/api/frontend` : '/api/frontend';

const request = async <T,>(path: string, options?: RequestInit): Promise<T> => {
  const headers: HeadersInit = {
    'Content-Type': 'application/json',
  };
  const res = await fetch(`${API_BASE}${path}`, {
    ...options,
    headers,
  });
  if (!res.ok) {
    const text = await res.text();
    console.error(`API ${res.status}: ${text || 'Error desconocido'}`);
    throw new Error(`API ${res.status}: ${text || 'Error desconocido'}`);
  }
  if (res.status === 204) return undefined as T;
  return res.json() as Promise<T>;
};

export const AppProvider = ({ children }: { children: ReactNode }) => {
  // === ESTADOS (Base de datos simulada) ===

  const [productos, setProductos] = useState<Producto[]>([]);
  const [empleados, setEmpleados] = useState<Empleado[]>([]);
  const [registros, setRegistros] = useState<RegistroDiario[]>([]);
  const [tareasAseo, setTareasAseo] = useState<TareaAseo[]>([]);

  useEffect(() => {
    let mounted = true;
    request<BootstrapResponse>('/bootstrap')
      .then((data) => {
        if (!mounted) return;
        setProductos(data.productos ?? []);
        setEmpleados(data.empleados ?? []);
        setRegistros(data.registros ?? []);
        setTareasAseo(data.tareasAseo ?? []);
      })
      .catch((err) => {
        console.warn('No se pudo cargar bootstrap del backend:', err);
      });
    return () => {
      mounted = false;
    };
  }, []);

  // === FUNCIONES CRUD ===

  // Producción
  const agregarProducto = (prod: Omit<Producto, 'id'>) => {
    request<Producto>('/productos', {
      method: 'POST',
      body: JSON.stringify(prod),
    })
      .then((nuevo) => {
        setProductos((prev) => [nuevo, ...prev]);
      })
      .catch((err) => console.error('Error creando producto:', err));
  };
  const editarProducto = (id: string, prod: Partial<Producto>) => {
    const actual = productos.find((p) => p.id === id);
    if (!actual) return;
    const payload = { ...actual, ...prod };
    request<Producto>(`/productos/${id}`, {
      method: 'PUT',
      body: JSON.stringify(payload),
    })
      .then((actualizado) => {
        setProductos((prev) => prev.map((p) => (p.id === id ? actualizado : p)));
      })
      .catch((err) => console.error('Error editando producto:', err));
  };
  const eliminarProducto = (id: string) => {
    request<void>(`/productos/${id}`, { method: 'DELETE' })
      .then(() => {
        setProductos((prev) => prev.filter((p) => p.id !== id));
        setRegistros((prev) =>
          prev.map((r) => ({
            ...r,
            producciones: (r.producciones ?? []).filter((p) => p.productoId !== id),
          }))
        );
      })
      .catch((err) => console.error('Error eliminando producto:', err));
  };

  // Empleados
  const agregarEmpleado = (emp: Omit<Empleado, 'id'>) => {
    request<Empleado>('/empleados', {
      method: 'POST',
      body: JSON.stringify(emp),
    })
      .then((nuevo) => {
        setEmpleados((prev) => [nuevo, ...prev]);
      })
      .catch((err) => console.error('Error creando empleado:', err));
  };
  const editarEmpleado = (id: string, emp: Partial<Empleado>) => {
    const actual = empleados.find((e) => e.id === id);
    if (!actual) return;
    const payload = { ...actual, ...emp };
    request<Empleado>(`/empleados/${id}`, {
      method: 'PUT',
      body: JSON.stringify(payload),
    })
      .then((actualizado) => {
        setEmpleados((prev) => prev.map((e) => (e.id === id ? actualizado : e)));
      })
      .catch((err) => console.error('Error editando empleado:', err));
  };
  const eliminarEmpleado = (id: string) => {
    request<void>(`/empleados/${id}`, { method: 'DELETE' })
      .then(() => {
        setEmpleados((prev) => prev.filter((e) => e.id !== id));
        setRegistros((prev) => prev.filter((r) => r.empleadoId !== id));
      })
      .catch((err) => console.error('Error eliminando empleado:', err));
  };

  // Registros
  const agregarRegistro = (reg: Omit<RegistroDiario, 'id'>) => {
    request<RegistroDiario>('/registros', {
      method: 'POST',
      body: JSON.stringify(reg),
    })
      .then((nuevo) => {
        setRegistros((prev) => [nuevo, ...prev]);
      })
      .catch((err) => console.error('Error creando registro:', err));
  };
  const eliminarRegistro = (id: string) => {
    request<void>(`/registros/${id}`, { method: 'DELETE' })
      .then(() => {
        setRegistros((prev) => prev.filter((r) => r.id !== id));
      })
      .catch((err) => console.error('Error eliminando registro:', err));
  };

  // Aseo
  const agregarTareaAseo = (tarea: Omit<TareaAseo, 'id'>) => {
    request<TareaAseo>('/tareas-aseo', {
      method: 'POST',
      body: JSON.stringify(tarea),
    })
      .then((nueva) => {
        setTareasAseo((prev) => [nueva, ...prev]);
      })
      .catch((err) => console.error('Error creando tarea de aseo:', err));
  };
  const editarTareaAseo = (id: string, tarea: Partial<TareaAseo>) => {
    const actual = tareasAseo.find((t) => t.id === id);
    if (!actual) return;
    const payload = { ...actual, ...tarea };
    request<TareaAseo>(`/tareas-aseo/${id}`, {
      method: 'PUT',
      body: JSON.stringify(payload),
    })
      .then((actualizada) => {
        setTareasAseo((prev) => prev.map((t) => (t.id === id ? actualizada : t)));
      })
      .catch((err) => console.error('Error editando tarea de aseo:', err));
  };
  const toggleTareaAseo = (id: string) => {
    request<TareaAseo>(`/tareas-aseo/${id}/toggle`, {
      method: 'PATCH',
    })
      .then((actualizada) => {
        setTareasAseo((prev) => prev.map((t) => (t.id === id ? actualizada : t)));
      })
      .catch((err) => console.error('Error cambiando estado de tarea:', err));
  };
  const eliminarTareaAseo = (id: string) => {
    request<void>(`/tareas-aseo/${id}`, { method: 'DELETE' })
      .then(() => {
        setTareasAseo((prev) => prev.filter((t) => t.id !== id));
      })
      .catch((err) => console.error('Error eliminando tarea de aseo:', err));
  };

  return (
    <AppContext.Provider value={{
      productos, agregarProducto, editarProducto, eliminarProducto,
      empleados, agregarEmpleado, editarEmpleado, eliminarEmpleado,
      registros, agregarRegistro, eliminarRegistro,
      tareasAseo, agregarTareaAseo, editarTareaAseo, toggleTareaAseo, eliminarTareaAseo
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useAppContext = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useAppContext debe usarse dentro de un AppProvider');
  return context;
};

import React, { createContext, useEffect, useState, useContext, ReactNode } from 'react';

// === MODELOS (Entidades) ===

export interface Producto {
  id: string;
  nombre: string;
  cantidad: number;
  empresa: string;
  ganancia: number;
  fechaAsignacion: string;
  fechaTerminacion: string;
  estado: 'Pendiente' | 'En proceso' | 'Terminado';
  pasos?: { descripcion: string; orden: number; completado?: boolean }[];
}

export interface Empleado {
  id: string;
  nombre: string;
  cargo: string;
  documento: string;
  telefono: string;
  fechaIngreso: string;
  estado: 'Activo' | 'Inactivo';
}

export interface Empresa {
  id: string;
  razonSocial: string;
  telefono?: string;
  correo?: string;
  direccion?: string;
  estado?: string; // Sin ordenes, Ordenes pendientes, Inactiva
}

export interface RegistroDiario {
  id: string;
  empleadoId: string;
  fecha: string;
  horaEntrada: string;
  horaSalida: string;
  unidadesTotales: number;
  unidadesBuenas: number; // Reemplaza la calificación 1-5 por número entero
  producciones?: ProduccionRegistro[];
}

/** Aporte del empleado vinculado a una orden creada en Producción (`Producto`). */
export interface ProduccionRegistro {
  productoId: string;
  unidadesTotales: number;
  unidadesBuenas: number;
}

export interface TareaAseo {
  id: string;
  accion: string; // Ej. Barrer, Trapear...
  area: string;   // Ej. Sala, Cocina...
  encargado: string;
  completada: boolean;
}

interface BootstrapResponse {
  productos: Producto[];
  empleados: Empleado[];
  registros: RegistroDiario[];
  tareasAseo: TareaAseo[];
}

// === TIPO DEL CONTEXTO ===

interface AppContextType {
  // Productos (Producción)
  productos: Producto[];
  agregarProducto: (prod: Omit<Producto, 'id'>) => void;
  editarProducto: (id: string, prod: Partial<Producto>) => void;
  eliminarProducto: (id: string) => void;

  // Empleados
  empleados: Empleado[];
  agregarEmpleado: (emp: Omit<Empleado, 'id'>) => void;
  editarEmpleado: (id: string, emp: Partial<Empleado>) => void;
  eliminarEmpleado: (id: string) => void;

  // Registros de Empleados
  registros: RegistroDiario[];
  agregarRegistro: (reg: Omit<RegistroDiario, 'id'>) => void;
  eliminarRegistro: (id: string) => void;

  // Aseo
  tareasAseo: TareaAseo[];
  agregarTareaAseo: (tarea: Omit<TareaAseo, 'id'>) => void;
  editarTareaAseo: (id: string, tarea: Partial<TareaAseo>) => void;
  toggleTareaAseo: (id: string) => void;
  eliminarTareaAseo: (id: string) => void;

  // Empresas
  empresas: Empresa[];
  agregarEmpresa: (emp: Omit<Empresa, 'id'>) => void;
  editarEmpresa: (id: string, emp: Partial<Empresa>) => void;
  eliminarEmpresa: (id: string) => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

/** En dev, Vite reenvía /api → backend (vite.config). En prod, define VITE_API_BASE_URL al desplegar el API. */
const fromEnv = import.meta.env.VITE_API_BASE_URL as string | undefined;
const API_BASE = fromEnv && fromEnv.trim() !== '' ? `${fromEnv.trim()}/api/frontend` : '/api/frontend';

const request = async <T,>(path: string, options?: RequestInit): Promise<T> => {
  const headers: HeadersInit = {
    'Content-Type': 'application/json',
  };
  const res = await fetch(`${API_BASE}${path}`, {
    ...options,
    headers,
  });
  if (!res.ok) {
    const text = await res.text();
    console.error(`API ${res.status}: ${text || 'Error desconocido'}`);
    throw new Error(`API ${res.status}: ${text || 'Error desconocido'}`);
  }
  if (res.status === 204) return undefined as T;
  return res.json() as Promise<T>;
};

export const AppProvider = ({ children }: { children: ReactNode }) => {
  // === ESTADOS (Base de datos simulada) ===

  const [productos, setProductos] = useState<Producto[]>([]);
  const [empleados, setEmpleados] = useState<Empleado[]>([]);
  const [registros, setRegistros] = useState<RegistroDiario[]>([]);
  const [tareasAseo, setTareasAseo] = useState<TareaAseo[]>([]);
  const [empresas, setEmpresas] = useState<Empresa[]>([]);

  useEffect(() => {
    let mounted = true;
    request<BootstrapResponse>('/bootstrap')
      .then((data) => {
        if (!mounted) return;
        setProductos(data.productos ?? []);
        setEmpleados(data.empleados ?? []);
        setRegistros(data.registros ?? []);
        setTareasAseo(data.tareasAseo ?? []);
        setEmpresas((data as any).empresas ?? []);
      })
      .catch((err) => {
        console.warn('No se pudo cargar bootstrap del backend:', err);
      });
    return () => {
      mounted = false;
    };
  }, []);

  // === FUNCIONES CRUD ===

  // Producción
  const agregarProducto = (prod: Omit<Producto, 'id'>) => {
    request<Producto>('/productos', {
      method: 'POST',
      body: JSON.stringify(prod),
    })
      .then((nuevo) => {
        setProductos((prev) => [nuevo, ...prev]);
      })
      .catch((err) => console.error('Error creando producto:', err));
  };
  const editarProducto = (id: string, prod: Partial<Producto>) => {
    const actual = productos.find((p) => p.id === id);
    if (!actual) return;
    const payload = { ...actual, ...prod };
    request<Producto>(`/productos/${id}`, {
      method: 'PUT',
      body: JSON.stringify(payload),
    })
      .then((actualizado) => {
        setProductos((prev) => prev.map((p) => (p.id === id ? actualizado : p)));
      })
      .catch((err) => console.error('Error editando producto:', err));
  };
  const eliminarProducto = (id: string) => {
    request<void>(`/productos/${id}`, { method: 'DELETE' })
      .then(() => {
        setProductos((prev) => prev.filter((p) => p.id !== id));
        setRegistros((prev) =>
          prev.map((r) => ({
            ...r,
            producciones: (r.producciones ?? []).filter((p) => p.productoId !== id),
          }))
        );
      })
      .catch((err) => console.error('Error eliminando producto:', err));
  };

  // Empleados
  const agregarEmpleado = (emp: Omit<Empleado, 'id'>) => {
    request<Empleado>('/empleados', {
      method: 'POST',
      body: JSON.stringify(emp),
    })
      .then((nuevo) => {
        setEmpleados((prev) => [nuevo, ...prev]);
      })
      .catch((err) => console.error('Error creando empleado:', err));
  };
  const editarEmpleado = (id: string, emp: Partial<Empleado>) => {
    const actual = empleados.find((e) => e.id === id);
    if (!actual) return;
    const payload = { ...actual, ...emp };
    request<Empleado>(`/empleados/${id}`, {
      method: 'PUT',
      body: JSON.stringify(payload),
    })
      .then((actualizado) => {
        setEmpleados((prev) => prev.map((e) => (e.id === id ? actualizado : e)));
      })
      .catch((err) => console.error('Error editando empleado:', err));
  };
  const eliminarEmpleado = (id: string) => {
    request<void>(`/empleados/${id}`, { method: 'DELETE' })
      .then(() => {
        setEmpleados((prev) => prev.filter((e) => e.id !== id));
        setRegistros((prev) => prev.filter((r) => r.empleadoId !== id));
      })
      .catch((err) => console.error('Error eliminando empleado:', err));
  };

  // Registros
  const agregarRegistro = (reg: Omit<RegistroDiario, 'id'>) => {
    request<RegistroDiario>('/registros', {
      method: 'POST',
      body: JSON.stringify(reg),
    })
      .then((nuevo) => {
        setRegistros((prev) => [nuevo, ...prev]);
      })
      .catch((err) => console.error('Error creando registro:', err));
  };
  const eliminarRegistro = (id: string) => {
    request<void>(`/registros/${id}`, { method: 'DELETE' })
      .then(() => {
        setRegistros((prev) => prev.filter((r) => r.id !== id));
      })
      .catch((err) => console.error('Error eliminando registro:', err));
  };

  // Aseo
  const agregarTareaAseo = (tarea: Omit<TareaAseo, 'id'>) => {
    request<TareaAseo>('/tareas-aseo', {
      method: 'POST',
      body: JSON.stringify(tarea),
    })
      .then((nueva) => {
        setTareasAseo((prev) => [nueva, ...prev]);
      })
      .catch((err) => console.error('Error creando tarea de aseo:', err));
  };
  const editarTareaAseo = (id: string, tarea: Partial<TareaAseo>) => {
    const actual = tareasAseo.find((t) => t.id === id);
    if (!actual) return;
    const payload = { ...actual, ...tarea };
    request<TareaAseo>(`/tareas-aseo/${id}`, {
      method: 'PUT',
      body: JSON.stringify(payload),
    })
      .then((actualizada) => {
        setTareasAseo((prev) => prev.map((t) => (t.id === id ? actualizada : t)));
      })
      .catch((err) => console.error('Error editando tarea de aseo:', err));
  };
  const toggleTareaAseo = (id: string) => {
    request<TareaAseo>(`/tareas-aseo/${id}/toggle`, {
      method: 'PATCH',
    })
      .then((actualizada) => {
        setTareasAseo((prev) => prev.map((t) => (t.id === id ? actualizada : t)));
      })
      .catch((err) => console.error('Error cambiando estado de tarea:', err));
  };
  const eliminarTareaAseo = (id: string) => {
    request<void>(`/tareas-aseo/${id}`, { method: 'DELETE' })
      .then(() => {
        setTareasAseo((prev) => prev.filter((t) => t.id !== id));
      })
      .catch((err) => console.error('Error eliminando tarea de aseo:', err));
  };

  // Empresas
  const agregarEmpresa = (emp: Omit<Empresa, 'id'>) => {
    request<Empresa>('/empresas', {
      method: 'POST',
      body: JSON.stringify(emp),
    })
      .then((nuevo) => setEmpresas((prev) => [nuevo, ...prev]))
      .catch((err) => console.error('Error creando empresa:', err));
  };

  const editarEmpresa = (id: string, emp: Partial<Empresa>) => {
    const actual = empresas.find((e) => e.id === id);
    if (!actual) return;
    const payload = { ...actual, ...emp };
    request<Empresa>(`/empresas/${id}`, { method: 'PUT', body: JSON.stringify(payload) })
      .then((actualizado) => setEmpresas((prev) => prev.map((e) => (e.id === id ? actualizado : e))))
      .catch((err) => console.error('Error editando empresa:', err));
  };

  const eliminarEmpresa = (id: string) => {
    request<void>(`/empresas/${id}`, { method: 'DELETE' })
      .then(() => setEmpresas((prev) => prev.filter((e) => e.id !== id)))
      .catch((err) => console.error('Error eliminando empresa:', err));
  };

  return (
    <AppContext.Provider value={{
      productos, agregarProducto, editarProducto, eliminarProducto,
      empleados, agregarEmpleado, editarEmpleado, eliminarEmpleado,
      registros, agregarRegistro, eliminarRegistro,
      tareasAseo, agregarTareaAseo, editarTareaAseo, toggleTareaAseo, eliminarTareaAseo,
      empresas, agregarEmpresa, editarEmpresa, eliminarEmpresa
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useAppContext = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useAppContext debe usarse dentro de un AppProvider');
  return context;
};

